  <title>عنوان التوصيل</title>
  <style>
    :root {
      --green: #087f4d;
      --green-dark: #05633c;
      --green-light: #e9f7ef;
      --text: #17211c;
      --muted: #6b756f;
      --line: #dfe5e1;
      --background: #f7f9f8;
      --error: #c93636;
    }

    * {
      box-sizing: border-box;
    }

    body {
      margin: 0;
