<body>
  <main class="page">
    <header class="header">
      <button class="back" type="button" aria-label="العودة">‹</button>
      <h1>عنوان التوصيل</h1>
      <p class="subtitle">أدخل تفاصيل العنوان حتى نوصل طلبك إلى.location الصحيح.</p>
    </header>

    <form id="addressForm" novalidate>
      <div class="success" id="successMessage" role="status">تم حفظ عنوان التوصيل بنجاح.</div>

      <section class="section" aria-labelledby="locationTitle">
        <h2 class="section-title" id="locationTitle">معلومات الموقع</h2>

        <div class="field">
          <label for="emirate">الإمارة</label>
          <select id="emirate" name="emirate">
            <option value="dubai" selected>دبي</option>
            <option value="abu-dhabi">أبوظبي</option>
            <option value="sharjah">الشارقة</option>
            <option value="ajman">عجمان</option>
            <option value="umm-al-quwain">أم القيوين</option>
            <option value="ras-al-khaimah">رأس الخيمة</option>
            <option value="fujairah">الفجيرة</option>
          </select>
        </div>

        <div class="field">
          <label for="building">رقم المبنى أو الفيلا</label>
          <input id="building" name="building" type="text" inputmode="numeric" placeholder="مثال: مبنى 12" autocomplete="address-line2" required>
          <div class="error-message" id="buildingError">يرجى إدخال رقم المبنى أو الفيلا.</div>
        </div>

        <div class="field">
          <label for="street">الشارع</label>
          <input id="street" name="street" type="text" placeholder="اسم الشارع" autocomplete="address-line1" required>
          <div class="error-message" id="streetError">يرجى إدخال اسم الشارع.</div>
        </div>

        <div class="field">
          <label for="area">المنطقة</label>
          <input id="area" name="area" type="text" placeholder="مثال: دبي مول" autocomplete="address-level3" required>
          <div class="error-message" id="areaError">يرجى إدخال اسم المنطقة.</div>
        </div>

        <div class="field">
          <label for="makani">رقم makani <span class="optional">(اختياري)</span></label>
          <input id="makani" name="makani" type="text" inputmode="numeric" placeholder="أدخل رقم makeni" autocomplete="off">
        </div>
      </section>

      <section class="section" aria-labelledby="contactTitle">
        <h2 class="section-title" id="contactTitle">بيانات التواصل</h2>

        <div class="field">
          <label for="phone">رقم الهاتف</label>
          <input id="phone" name="phone" type="tel" placeholder="050 123 4567" autocomplete="tel" required>
          <div class="error-message" id="phoneError">يرجى إدخال رقم هاتف صحيح.</div>
        </div>
      </section>

      <button class="save-button" id="saveButton" type="submit">حفظ العنوان</button>
    </form>
  </main>

  <script>
    const form = document.getElementById('addressForm');
    const successMessage = document.getElementById('successMessage');
    const saveButton = document.getElementById('saveButton');

    function showError(id, messageId, show) {
      const field = document.getElementById(id);
      const error = document.getElementById(messageId);
      field.classList.toggle('invalid', show);
      field.setAttribute('aria-invalid', show ? 'true' : 'false');
      error.classList.toggle('visible', show);
      return !show;
    }

    form.addEventListener('submit', function (event) {
      event.preventDefault();
      successMessage.classList.remove('visible');

      const building = document.getElementById('building');
      const street = document.getElementById('street');
      const area = document.getElementById('area');
      const phone = document.getElementById('phone');

      const validBuilding = showError('building', 'buildingError', !building.value.trim());
      const validStreet = showError('street', 'streetError', !street.value.trim());
      const validArea = showError('area', 'areaError', !area.value.trim());
      const validPhone = showError('phone', 'phoneError', phone.value.replace(/\D/g, '').length < 10);

      if (!validBuilding || !validStreet || !validArea || !validPhone) {
        const firstInvalid = form.querySelector('.invalid');
        if (firstInvalid) firstInvalid.focus();
        return;
      }

      saveButton.disabled = true;
      saveButton.textContent = 'جارٍ الحفظ...';

      setTimeout(function () {
        saveButton.disabled = false;
        saveButton.textContent = 'حفظ العنوان';
        successMessage.classList.add('visible');
        successMessage.scrollIntoView({ behavior: 'smooth', block: 'nearest' });
      }, 500);
    });

    document.querySelectorAll('input').forEach(function (input) {
      input.addEventListener('input', function () {
        input.classList.remove('invalid');
        input.setAttribute('aria-invalid', 'false');
        const error = document.getElementById(input.id + 'Error');
        if (error) error.classList.remove('visible');
      });
    });
  </script>
</body>
</html>
